package zw.ac.msu.dzimbahub.controller;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import zw.ac.msu.dzimbahub.auth.*; import zw.ac.msu.dzimbahub.model.*; import zw.ac.msu.dzimbahub.repository.*; import java.util.*;
@RestController public class OperationsController {
 private final UserActionRepository actions; private final PropertyRepository properties; private final AppUserRepository users;
 public OperationsController(UserActionRepository a,PropertyRepository p,AppUserRepository u){actions=a;properties=p;users=u;}
 public record ActionRequest(@NotNull Long propertyId, @Size(max=2000) String message, @Min(1) @Max(5) Integer rating, @Size(max=2000) String comment, String date, String time){}
 private AppUser current(Authentication a){if(a==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 private Property property(Long id){return properties.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Property not found."));}
 private ResponseEntity<?> create(String type,ActionRequest r,Authentication a){AppUser u=current(a);if(u.getRole()!=UserRole.TENANT)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only tenants can submit this request.");Property p=property(r.propertyId());if(type.equals("MESSAGE")&&(r.message()==null||r.message().isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter an enquiry message.");if(type.equals("REVIEW")&&(r.rating()==null||r.comment()==null||r.comment().isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Select a rating and enter a review.");if(type.equals("VIEWING")&&(r.date()==null||r.time()==null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a viewing date and time.");String landlordEmail=null;if(p.getLandlordId()!=null)landlordEmail=users.findById(p.getLandlordId()).map(AppUser::getEmail).orElse(null);UserAction a1=actions.save(new UserAction(type,p.getId(),u.getEmail(),landlordEmail,r.message(),r.rating(),r.comment(),r.date(),r.time()));if(type.equals("REVIEW")){List<UserAction> reviews=actions.findAll().stream().filter(x->x.getType().equals("REVIEW")&&Objects.equals(x.getPropertyId(),p.getId())&&x.getRating()!=null).toList();double average=reviews.stream().mapToInt(UserAction::getRating).average().orElse(0);p.setRating(Math.round(average*10.0)/10.0);p.setReviewCount(reviews.size());properties.save(p);}return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("id",a1.getId(),"message",type.equals("MESSAGE")?"Enquiry sent to the landlord.":type.equals("REVIEW")?"Your rating and review were submitted.":"Viewing request submitted.","status",a1.getStatus()));}
 @PostMapping("/api/messages") public ResponseEntity<?> message(@Valid @RequestBody ActionRequest r,Authentication a){return create("MESSAGE",r,a);}
 @PostMapping("/api/reviews") public ResponseEntity<?> review(@Valid @RequestBody ActionRequest r,Authentication a){return create("REVIEW",r,a);}
 @PostMapping("/api/viewings") public ResponseEntity<?> viewing(@Valid @RequestBody ActionRequest r,Authentication a){return create("VIEWING",r,a);}
 @GetMapping("/api/tenant/actions") public List<UserAction> tenantActions(Authentication a){AppUser u=current(a);if(u.getRole()!=UserRole.TENANT)throw new ResponseStatusException(HttpStatus.FORBIDDEN);return actions.findByTenantEmailOrderByCreatedAtDesc(u.getEmail());}
 @GetMapping("/api/landlord/actions") public List<UserAction> landlordActions(Authentication a){AppUser u=current(a);if(u.getRole()!=UserRole.LANDLORD)throw new ResponseStatusException(HttpStatus.FORBIDDEN);return actions.findByLandlordEmailOrderByCreatedAtDesc(u.getEmail());}
 @PutMapping("/api/landlord/actions/{id}/status") public Map<String,Object> updateAction(@PathVariable Long id,@RequestBody Map<String,String> body,Authentication a){AppUser u=current(a);if(u.getRole()!=UserRole.LANDLORD)throw new ResponseStatusException(HttpStatus.FORBIDDEN);UserAction action=actions.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!u.getEmail().equalsIgnoreCase(action.getLandlordEmail()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This request belongs to another landlord.");String status=body.getOrDefault("status","");if(!List.of("ACCEPTED","DECLINED","RESPONDED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported status.");action.setStatus(status);actions.save(action);return Map.of("id",id,"status",status);}
}
